import { Easing } from "./Easing";
import { execute as jobStopService } from "./Job/service/JobStopService";
import { execute as jobStartUseCase } from "./Job/usecase/JobStartUseCase";
import { EventDispatcher } from "@next2d/events";
/**
 * @class
 * @memberOf next2d.ui
 * @extends  EventDispatcher
 */
export class Job extends EventDispatcher {
    /**
     * @param {object}   target
     * @param {object}   [from=null]
     * @param {object}   [to=null]
     * @param {number}   [delay=0]
     * @param {number}   [duration=1]
     * @param {function} [ease=null]
     *
     * @constructor
     * @public
     */
    constructor(target, from, to, delay = 0, duration = 1, ease = null) {
        super();
        /**
         * @description イージングの対象オブジェクト
         *              Target object of easing
         *
         * @type {object}
         * @default null
         * @public
         */
        Object.defineProperty(this, "target", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        /**
         * @description イージングのエントリーオブジェクト
         *              Entry object of easing
         *
         * @type {array}
         * @default null
         * @public
         */
        Object.defineProperty(this, "entries", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        /**
         * @description イージングの開始時間
         *              Start time of easing
         *
         * @type {number}
         * @default 0
         * @public
         */
        Object.defineProperty(this, "startTime", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        /**
         * @description イージングの強制停止フラグ
         *              Forced stop flag of easing
         *
         * @type {boolean}
         * @default false
         * @public
         */
        Object.defineProperty(this, "stopFlag", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        /**
         * @description イージングの遅延実行のタイマーID
         *              Timer ID for delayed execution of easing
         *
         * @type {number}
         * @default -1
         * @protected
         */
        Object.defineProperty(this, "$timerId", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        /**
         * @description イージングの開始までの遅延時間を返します。
         *              Returns the delay time until the start of the easing.
         *
         * @type {number}
         * @default 0
         * @public
         */
        Object.defineProperty(this, "delay", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        /**
         * @description イージング完了時間を返します。
         *              Returns the easing completion time.
         *
         * @type {number}
         * @default 1
         * @public
         */
        Object.defineProperty(this, "duration", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        /**
         * @description イージングの計算関数を返します。
         *              Returns the calculation function of the easing.
         *
         * @see Easing
         * @type {function}
         * @default Easing.linear
         * @public
         */
        Object.defineProperty(this, "ease", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        /**
         * @description イージングの開始オブジェクトを返します。
         *              Returns the start object of the easing.
         *
         * @type {object}
         * @public
         */
        Object.defineProperty(this, "from", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        /**
         * @description イージングの終了オブジェクトを返します。
         *              Returns the end object of the easing.
         *
         * @type {object}
         * @public
         */
        Object.defineProperty(this, "to", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        /**
         * @description イージングの現在時間を返します。
         *              Returns the current time of the easing.
         *
         * @type {number}
         * @default 0
         * @public
         */
        Object.defineProperty(this, "currentTime", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        /**
         * @description イージングの次のjobを返します。
         *              Returns the next job of the easing.
         *
         * @member {Job | null}
         * @default null
         * @readonly
         * @public
         */
        Object.defineProperty(this, "nextJob", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        this.target = target;
        this.from = from;
        this.to = to;
        this.delay = delay;
        this.duration = duration;
        this.ease = ease || Easing.linear;
        // default value
        this.currentTime = 0;
        this.nextJob = null;
        this.entries = null;
        this.startTime = 0;
        this.stopFlag = false;
        this.$timerId = -1;
    }
    /**
     * @description 指定したjobを次に開始します。nullで解消
     *              Starts the next specified job, resolved by null
     *
     * @return {Job | null}
     * @method
     * @public
     */
    chain(job) {
        this.nextJob = job;
        return job;
    }
    /**
     * @description イージングを開始します。
     *              Starts the easing.
     *
     * @return {void}
     * @method
     * @public
     */
    start() {
        jobStartUseCase(this);
    }
    /**
     * @description イージングを停止します。
     *              Stops the easing.
     *
     * @return {void}
     * @method
     * @public
     */
    stop() {
        jobStopService(this);
    }
}
